sys_script_include.script:
var Swift_Retry_Outbound = Class.create();
Swift_Retry_Outbound.prototype = {
    initialize: function() {},
    checkEnvironment: function() {
        var interval = gs.getProperty("x_hsb11_mss_c_swft.retry_interval_environment_check");
        var uri_prop = gs.getProperty("x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_url");
        var responseStatusFilter = gs.getProperty("x_hsb11_mss_c_swft.swift_status_code");
        var gr = new GlideRecord("sys_outbound_http_log");
        gr.addQuery("response_status", "NOT IN", responseStatusFilter.split(','));
        gr.addEncodedQuery(interval);
        gr.addQuery("url", "STARTSWITH", uri_prop);
        gr.query();
        if (gr.hasNext()) {
            return false;
        } else {
            return true;
        }
    },

    retry: function() {
        var retry_cnt = gs.getProperty("x_hsb11_mss_c_swft.swift_retry_count");
        var responseStatusFilter = gs.getProperty("x_hsb11_mss_c_swft.swift_status_code");
        var responseBodyEmpty = gs.getProperty("x_hsb11_mss_c_swft.swift_empty_response_body");
        var gr = new GlideRecord("x_hsb11_mss_c_swft_mss_custody_swift_ondemand_staging");
        gr.addEncodedQuery('response_code!=200^retry_count<'+retry_cnt+'^NQresponse_code=200^response_bodyLIKE"total":0^retry_count<'+retry_cnt); //MSSCUSTODY-8351
        // gr.addQuery("state", "Error");
        // gr.addQuery("response_code", "NOT IN", responseStatusFilter.split(','));
        // gr.addQuery("retry_count", "<", retry_cnt);
        // MSSCUSTODY-3596 : Added condition for completed swift. Condition after NQ is new condition

        //hiding as part of MSSCUSTODY-8351
        //gr.addEncodedQuery("state=Error^response_codeNOT IN"+responseStatusFilter.split(',')+"^retry_count<"+retry_cnt+"^NQstate=Processed^response_body="+responseBodyEmpty+"^retry_count<"+retry_cnt);
        gr.query();
        while (gr.next()) {
            gr.state = "Ready to be sent";
            gr.retry_count = gr.retry_count + 1;
            gr.update();
        }
    },

    type: 'Swift_Retry_Outbound'
};
